/* ═══════════ CURTO PRAZO — Market Share ═══════════ */
function renderShrShortTerm(mkt){
  var wrap=document.getElementById('shr-st-wrap');
  if(!wrap)return;
  var d=SHR_TREND_DATA[mkt];
  if(!d){wrap.style.display='none';return;}
  wrap.style.display='block';
  var brands=['OFF!','EXPOSIS','XO INSETO','SUPER REPELEX','SBP'];
  function _ser(br){var bd=d[br];if(!bd||!bd.fy26)return [];return (bd.fy25||new Array(12).fill(null)).concat(bd.fy26);}
  function gv(br,idx){var s=_ser(br);return (idx>=0&&s[idx]!=null)?s[idx]:null;}
  var _ref=_ser('OFF!').length?_ser('OFF!'):_ser('XO INSETO'); var JUN=_ref.reduce(function(a,v,i){return v!=null?i:a;},11);
  var MAI=JUN-1,ABR=JUN-2,MAR=JUN-3; var _L=nqSeriesLabels(mkt); var _l=function(i){return (_L[i]||'').toUpperCase();};
  function dc(v){return v==null?'#64748B':(v>0?'#16a34a':v<0?'#dc2626':'#94A3B8');}
  function fp(v){return v!=null?v.toFixed(2)+'%':'—';}
  function fd(v){if(v==null)return'—';return(v>=0?'+':'')+v.toFixed(2)+'pp';}
  var rows=brands.map(function(br){
    var a=gv(br,JUN),m=gv(br,MAI),f=gv(br,ABR),j=gv(br,MAR);
    var mom=(a!=null&&m!=null)?a-m:null;
    var bi26=(a!=null&&m!=null)?(a+m)/2:null;
    var bi25=(f!=null&&j!=null)?(f+j)/2:null;
    var d2m=(bi26!=null&&bi25!=null)?bi26-bi25:null;
    return{br:br,a:a,m:m,mom:mom,bi26:bi26,bi25:bi25,d2m:d2m};
  });
  // SCJ = OFF! + EXPOSIS
  var scja=0,scjm=0,scjf=0,scjj=0,ok=true;
  ['OFF!','EXPOSIS'].forEach(function(br){
    var a=gv(br,JUN),m=gv(br,MAI),f=gv(br,ABR),j=gv(br,MAR);
    if(a==null||m==null||f==null||j==null){ok=false;return;}
    scja+=a;scjm+=m;scjf+=f;scjj+=j;
  });
  if(ok){
    var smom=scja-scjm,sbi26=(scja+scjm)/2,sbi25=(scjf+scjj)/2,sd2m=sbi26-sbi25;
    rows.push({br:'SCJ (OFF!+EXPOSIS)',a:scja,m:scjm,mom:smom,bi26:sbi26,bi25:sbi25,d2m:sd2m,isSCJ:true});
  }
  var h='<table style="width:100%;border-collapse:collapse;font-size:11px;">';
  h+='<thead><tr style="border-bottom:1.5px solid rgba(45,90,142,0.35);">';
  h+='<th style="padding:5px 8px;text-align:left;color:#64748b;font-size:9px;font-weight:700;letter-spacing:.08em;">MARCA</th>';
  h+='<th style="padding:5px 8px;text-align:right;color:#1D6FA8;font-size:9px;font-weight:700;">'+_l(JUN)+'</th>';
  h+='<th style="padding:5px 8px;text-align:right;color:#64748b;font-size:9px;font-weight:700;">'+_l(MAI)+'</th>';
  h+='<th style="padding:5px 8px;text-align:right;color:#1E293B;font-size:9px;font-weight:700;">Δ MoM</th>';
  h+='<th style="padding:5px 8px;text-align:right;color:#1D6FA8;font-size:9px;font-weight:700;border-left:1px solid rgba(45,90,142,0.25);">'+_L[JUN].split('/')[0]+'+'+_L[MAI].split('/')[0]+'</th>';
  h+='<th style="padding:5px 8px;text-align:right;color:#64748b;font-size:9px;font-weight:700;">'+_L[ABR].split('/')[0]+'+'+_L[MAR].split('/')[0]+'</th>';
  h+='<th style="padding:5px 8px;text-align:right;color:#1E293B;font-size:9px;font-weight:700;">Δ 2M</th>';
  h+='</tr></thead><tbody>';
  rows.forEach(function(r){
    var scjStyle=r.isSCJ?'border-top:1.5px solid rgba(45,90,142,0.35);background:rgba(45,90,142,0.07);':'';
    var brc=r.isSCJ?'#2D5A8E':(_shrBrandColors[r.br]||'#1E293B');
    h+='<tr style="'+scjStyle+'">';
    h+='<td style="padding:4px 8px;font-weight:700;color:'+brc+';font-size:11px;">'+r.br+'</td>';
    h+='<td style="padding:4px 8px;text-align:right;color:#1E293B;font-weight:700;">'+fp(r.a)+'</td>';
    h+='<td style="padding:4px 8px;text-align:right;color:#64748B;">'+fp(r.m)+'</td>';
    h+='<td style="padding:4px 8px;text-align:right;font-weight:800;color:'+dc(r.mom)+';">'+fd(r.mom)+'</td>';
    h+='<td style="padding:4px 8px;text-align:right;color:#1E293B;font-weight:700;border-left:1px solid rgba(45,90,142,0.25);">'+fp(r.bi26)+'</td>';
    h+='<td style="padding:4px 8px;text-align:right;color:#64748B;">'+fp(r.bi25)+'</td>';
    h+='<td style="padding:4px 8px;text-align:right;font-weight:800;color:'+dc(r.d2m)+';">'+fd(r.d2m)+'</td>';
    h+='</tr>';
  });
  h+='</tbody></table>';
  h+='<div style="font-size:9px;color:#475569;margin-top:6px;">Δ MoM = '+_L[JUN]+' − '+_L[MAI]+' &nbsp;|&nbsp; Δ 2M = média ('+_L[JUN]+' + '+_L[MAI]+') − média ('+_L[ABR]+' + '+_L[MAR]+')'+nqFY(mkt).base+'</div>';
  var tEl=document.getElementById('shr-st-table');
  if(tEl)tEl.innerHTML=h;
}
function toggleShrST(){
  var t=document.getElementById('shr-st-table');
  var btn=document.getElementById('shr-st-btn');
  if(!t||!btn)return;
  var open=t.style.display!=='none';
  t.style.display=open?'none':'block';
  btn.innerHTML=open?'&#9658; Análise Curto Prazo':'&#9660; Análise Curto Prazo';
}

