// Real renderVolMkt — defined in block 9 scope alongside VOL_MKT_HIST
window._renderVolMktImpl = function(){

  var mkt = (document.getElementById('volMktSel')||{value:'T.BR Farma'}).value || 'T.BR Farma';
  if(typeof VOL_MKT_HIST==='undefined') return;
  var d = VOL_MKT_HIST[mkt]; if(!d) return;
  var isVal = _volMetric==='val';

  var fy24 = isVal ? d.fy24_val : d.fy24_un;
  var fy25 = isVal ? d.fy25_val : d.fy25_un;
  var fy26 = isVal ? d.fy26_val : d.fy26_un;
  var fy24_tot = isVal ? d.fy24_total_val : d.fy24_total_un;
  var fy25_tot = isVal ? d.fy25_total_val : d.fy25_total_un;
  var fy26_p   = isVal ? d.fy26_proj_val  : d.fy26_proj_un;
  var unit = isVal ? 'R$M' : 'k un';

  // KPIs
  var d25 = fy24_tot>0 ? ((fy25_tot-fy24_tot)/fy24_tot*100).toFixed(1) : '–';
  var d26 = fy25_tot>0 ? ((fy26_p-fy25_tot)/fy25_tot*100).toFixed(1)  : '–';
  var fmt = function(v){ return isVal ? window.NF.revM(v) : window.NF.volK(v); };
  var kpiEl = document.getElementById('vol-kpis');
  if(kpiEl){
    var kpiData = [
      {yr:'FY24',val:fmt(fy24_tot),d:null,bdr:'#fbbf24',bg:'rgba(251,191,36,0.08)'},
      {yr:'FY25',val:fmt(fy25_tot),d:d25,bdr:'#34d399',bg:'rgba(52,211,153,0.08)'},
      {yr:'FY26 Proj.',val:fmt(fy26_p),d:d26,bdr:'#60a5fa',bg:'rgba(96,165,250,0.08)'}
    ];
    kpiEl.innerHTML = kpiData.map(function(k){
      var dStr = k.d!==null ? '<div style="font-size:10px;font-weight:700;color:'+(parseFloat(k.d)>=0?'#34d399':'#fb7185')+';">'+(parseFloat(k.d)>=0?'+':'')+k.d+'% vs anterior</div>' : '';
      return '<div style="background:#EAEEF4;border-radius:12px;padding:14px 16px;border-top:3px solid '+k.bdr+';border-left:1px solid rgba(147,187,235,0.5);border-right:1px solid rgba(147,187,235,0.5);border-bottom:1px solid rgba(147,187,235,0.5);box-shadow:0 2px 8px rgba(10,40,80,0.12);">'
        +'<div style="font-size:9px;font-weight:700;color:#475569;letter-spacing:.08em;text-transform:uppercase;margin-bottom:4px;">'+k.yr+'</div>'
        +'<div style="font-size:17px;font-weight:800;color:'+k.bdr+';line-height:1;margin-bottom:3px;">'+k.val+'</div>'
        +dStr+'</div>';
    }).join('');
  }

  var MOS = ['Jul','Ago','Set','Out','Nov','Dez','Jan','Fev','Mar','Abr','Mai','Jun'];

  // ── LINE CHART ─────────────────────────────────────────────────────────────
  var lCtx = document.getElementById('vol-line-chart');
  if(lCtx){
    // Force canvas to pick up container dimensions before Chart.js measures it
    var _lPar = lCtx.parentElement;
    if(_lPar && _lPar.offsetWidth > 0){ lCtx.width = _lPar.offsetWidth; lCtx.height = _lPar.offsetHeight || 260; }
    if(_volLineChart){ _volLineChart.destroy(); _volLineChart=null; }
    _volLineChart = new Chart(lCtx.getContext('2d'),{
      type:'line',
      data:{
        labels:MOS,
        datasets:[
          {label:'FY24',data:fy24,borderColor:'#fbbf24',backgroundColor:'rgba(251,191,36,0.08)',borderWidth:2,pointRadius:3,pointBackgroundColor:'#fbbf24',tension:0.3,fill:false},
          {label:'FY25',data:fy25,borderColor:'#34d399',backgroundColor:'rgba(52,211,153,0.08)',borderWidth:2,pointRadius:3,pointBackgroundColor:'#34d399',tension:0.3,fill:false},
          {label:'FY26 (parcial)',data:fy26,borderColor:'#60a5fa',backgroundColor:'rgba(96,165,250,0.06)',borderWidth:2,borderDash:[6,3],pointRadius:3,pointBackgroundColor:'#60a5fa',tension:0.3,fill:false}
        ]
      },
      options:{
        responsive:true,maintainAspectRatio:false,
        plugins:{
          legend:{display:true,position:'top',labels:{color:'#9ca3af',font:{size:10},boxWidth:14,padding:12}},
          tooltip:{callbacks:{label:function(c){return c.dataset.label+': '+(c.parsed.y!==null?(isVal?window.NF.revMTip(c.parsed.y):window.NF.volKTip(c.parsed.y)):'—');}}}
        },
        scales:{
          x:{ticks:{color:'#94A3B8',font:{size:9}},grid:{color:'rgba(255,255,255,0.04)'}},
          y:{ticks:{color:'#94A3B8',font:{size:9},callback:function(v){return isVal?window.NF.axisRev(v):window.NF.axisVol(v);}},grid:{color:'rgba(245,225,164,0.07)'}}
        }
      }
    });
    setTimeout(function(){ if(_volLineChart) _volLineChart.resize(); }, 600);
    setTimeout(function(){ if(_volLineChart) _volLineChart.resize(); }, 1500);
  }

  // ── BAR CHART — FYTD25 vs FYTD26 ──────────────────────────────────────────
  var bCtx = document.getElementById('vol-bar-chart');
  if(bCtx){
    var _bPar = bCtx.parentElement;
    if(_bPar && _bPar.offsetWidth > 0){ bCtx.width = _bPar.offsetWidth; bCtx.height = _bPar.offsetHeight || 260; }
    if(_volBarChart){ _volBarChart.destroy(); _volBarChart=null; }
    var fytd25_bar = isVal ? (d.fy25_fytd_val||0) : (d.fy25_fytd_un||0);
    var fytd26_bar = isVal ? (d.fy26_fytd_val||0) : (d.fy26_fytd_un||0);
    var fytd_delta = fytd25_bar>0 ? ((fytd26_bar-fytd25_bar)/fytd25_bar*100).toFixed(1) : null;
    var fytd_deltaColor = fytd_delta!==null ? (parseFloat(fytd_delta)>=0?'#34d399':'#fb7185') : '#9ca3af';
    var barVals   = [fytd25_bar, fytd26_bar];
    var barColors = ['rgba(156,163,175,0.55)', parseFloat(fytd_delta)>=0?'rgba(52,211,153,0.85)':'rgba(239,68,68,0.75)'];
    var barBorders= ['rgba(156,163,175,0.8)', parseFloat(fytd_delta)>=0?'#34d399':'#ef4444'];
    _volBarChart = new Chart(bCtx.getContext('2d'),{
      type:'bar',
      data:{
        labels:['FYTD25\nJul/24–Abr/25','FYTD26\nJul/25–Abr/26'],
        datasets:[{
          data:barVals,
          backgroundColor:barColors,
          borderColor:barBorders,
          borderWidth:2,
          borderRadius:8,
          borderSkipped:false,
          barPercentage:0.55
        }]
      },
      options:{
        responsive:true,maintainAspectRatio:false,
        plugins:{
          legend:{display:false},
          tooltip:{callbacks:{label:function(c){return ' '+fmt(c.parsed.y);}}}
        },
        scales:{
          x:{ticks:{color:'#475569',font:{size:10,weight:'700'}},grid:{display:false}},
          y:{ticks:{color:'#94A3B8',font:{size:9},callback:function(v){return isVal?window.NF.axisRev(v):window.NF.axisVol(v);}},grid:{color:'rgba(245,225,164,0.07)'},beginAtZero:true}
        }
      },
      plugins:[{
        id:'fytdDeltaLabel',
        afterDatasetsDraw:function(chart){
          var ctx2=chart.ctx; ctx2.save();
          var meta=chart.getDatasetMeta(0);
          // delta label acima da barra FYTD26
          var bar=meta.data[1]; if(!bar||fytd_delta===null) return;
          ctx2.textAlign='center'; ctx2.font='bold 11px sans-serif';
          ctx2.fillStyle=fytd_deltaColor;
          ctx2.fillText((parseFloat(fytd_delta)>=0?'+':'')+fytd_delta+'%', bar.x, bar.y-8);
          // valor absoluto acima de cada barra
          meta.data.forEach(function(b,i){
            ctx2.font='10px sans-serif';
            ctx2.fillStyle='#9ca3af';
            ctx2.fillText(fmt(barVals[i]), b.x, b.y-(i===1&&fytd_delta!==null?24:8));
          });
          ctx2.restore();
        }
      }]
    });
    setTimeout(function(){ if(_volBarChart) _volBarChart.resize(); }, 600);
    setTimeout(function(){ if(_volBarChart) _volBarChart.resize(); }, 1500);
  }

};

