(function(){
  var _regVolChart    = null;
  var _regContribChart = null;

  function _getMkts(grupo){
    var allMkts = Object.keys(FYTD_MARKET_TOTAL);
    if (grupo === 'farma_sud') {
      return ['Farma Sul','Farma Moderno Sul','Farma Indep Sul','INFC Sul','T.BR Farma',
              'Farma NE','INFC NE','Farma CO','INFC CO'];
    } else if (grupo === 'farma_mod') {
      return allMkts.filter(function(m){ return /^Farma Moderno/.test(m); });
    } else if (grupo === 'farma_ind') {
      return allMkts.filter(function(m){ return /^Farma Indep/.test(m); });
    } else if (grupo === 'farma') {
      return allMkts.filter(function(m){ return /^Farma/.test(m); });
    } else if (grupo === 'infc_sul') {
      return allMkts.filter(function(m){
        return /^INFC/.test(m) && (/Sul$|^INFC RS$|^INFC SC$|^INFC PR$|Curitiba|Porto/.test(m));
      });
    } else if (grupo === 'tbr') {
      return allMkts.filter(function(m){ return /^T\.BR/.test(m); });
    } else if (grupo === 'top15') {
      return allMkts.slice().sort(function(a,b){
        return FYTD_MARKET_TOTAL[b].fytd26_val - FYTD_MARKET_TOTAL[a].fytd26_val;
      }).slice(0,15);
    }
    return allMkts; /* todos */
  }

  function _destroyChart(c){ if(c){ try{ c.destroy(); }catch(e){} } return null; }

  function _resetCanvas(id){
    var cv = document.getElementById(id); if(!cv) return null;
    cv.removeAttribute('width'); cv.removeAttribute('height');
    cv.style.removeProperty('width'); cv.style.removeProperty('height');
    return cv;
  }

  })();
