var _adCharts={};
function renderAreaDecomp(){
  if(typeof AREA_DECOMP==='undefined')return;
  var brand=(document.getElementById('adBrandSel')||{value:'EXPOSIS'}).value;
  var grp=(document.getElementById('adGrpSel')||{value:'Farma Moderno'}).value;
  var G=AREA_DECOMP[grp]; if(!G||!G[brand])return;
  var areas=G.areas, d=G[brand];
  var n=areas.length;
  var idx=Array.from({length:n},function(_,i){return i;}).sort(function(a,b){return d.val26[b]-d.val26[a];});
  var labels=idx.map(function(i){return areas[i];});
  var val=idx.map(function(i){return d.val26[i];});
  var vr=idx.map(function(i){return d.var[i];});
  var ct=idx.map(function(i){return d.contrib[i];});
  var brLbl={'EXPOSIS':'Exposis','OFF!':'OFF!','XO INSETO':'Xô Inseto','SUPER REPELEX':'Super Repelex'}[brand]||brand;
  var sub=document.getElementById('area-decomp-sub');
  var _adOld=!!AD_BASE_ANTERIOR[grp], _ad6=!_adOld&&NQ_FY==='FY26', _adR=!_adOld&&NQ_FY==='ROLL', _adK=!_adOld&&NQ_FY==='CAL', _adP=_adOld?'FYTD25':(_ad6?'FY25':(_adK?nqCalP().perP:(_adR?'12M ant.':'FYTD26'))), _adC=_adOld?'FYTD26':(_ad6?'FY26':(_adK?nqCalP().perC:(_adR?'Últ. 12M':'FYTD27')));
  if(sub)sub.textContent=brLbl+' · '+grp+' · '+_adC+' vs '+_adP+(_adOld?' · base anterior':(_ad6?' (Jul–Jun)':(_adK?' (ano-calendário)':_adR?' ('+nqL12().perC+')':' (Jul–Out)')))+' · Personal Repellent';
  var _adT=document.getElementById('area-decomp-title'); if(_adT) _adT.textContent='CONTRIBUIÇÃO DE SHARE POR ÁREA — '+_adC+' vs '+_adP;
  var _adN=document.getElementById('area-decomp-note'); if(_adN) _adN.textContent='Contribuição = (Valor marca/Total agrupamento '+_adC+') − (idem '+_adP+'). Soma das contribuições = variação total de share do agrupamento. Fonte: NielsenIQ · '+(_adOld?'Base Giovano (25-05) — base anterior.':'Base Padrão dash - Out26 (export 03/11/2026).');
  // insight: top contribuidores negativos
  var totVar=ct.reduce(function(s,v){return s+v;},0);
  var negs=idx.map(function(i){return{a:areas[i],c:d.contrib[i]};}).filter(function(x){return x.c<0;}).sort(function(a,b){return a.c-b.c;});
  var negSum=negs.reduce(function(s,x){return s+x.c;},0);
  var insEl=document.getElementById('area-decomp-insight');
  if(insEl){
    var dir=totVar<0?'perda':'ganho';
    var txt='<strong>'+brLbl+'</strong> no '+grp+': variação total de share = <strong style="color:'+(totVar>=0?'#0E9F6E':'#dc2626')+'">'+(totVar>=0?'+':'')+totVar.toFixed(2)+'pp</strong>. ';
    if(negs.length>=2&&negSum<0){
      txt+='Áreas que mais pesaram contra: <strong>'+negs[0].a+'</strong> ('+Math.round(negs[0].c/negSum*100)+'%) e <strong>'+negs[1].a+'</strong> ('+Math.round(negs[1].c/negSum*100)+'%).';
    }
    insEl.innerHTML=txt;
  }
  function hbar(cid,data,colors,fmt,axfmt){
    if(_adCharts[cid]){try{_adCharts[cid].destroy();}catch(e){}}
    var c=document.getElementById(cid); if(!c)return;
    _adCharts[cid]=new Chart(c,{type:'bar',data:{labels:labels,datasets:[{data:data,backgroundColor:colors,borderColor:colors,borderWidth:0,borderRadius:3}]},
      options:{indexAxis:'y',responsive:true,maintainAspectRatio:false,
        plugins:{legend:{display:false},tooltip:{callbacks:{label:function(x){return fmt(x.parsed.x);}}}},
        scales:{x:{ticks:{color:'#94A3B8',font:{size:9},callback:axfmt},grid:{color:'rgba(59,130,246,0.08)'}},
                y:{ticks:{color:'#1e293b',font:{size:9.5,weight:'600'}},grid:{display:false}}}}});
  }
  hbar('ad-bar-val',val,val.map(function(){return '#93c5fd';}),
       function(v){return 'R$ '+v.toFixed(2)+' MM';},function(v){return 'R$'+v;});
  hbar('ad-bar-var',vr,vr.map(function(v){return v>=0?'#15803d':'#b91c1c';}),
       function(v){return (v>=0?'+':'')+v.toFixed(2)+'pp';},function(v){return (v>=0?'+':'')+v+'pp';});
  hbar('ad-bar-contrib',ct,ct.map(function(v){return v>=0?'#15803d':'#b91c1c';}),
       function(v){return (v>=0?'+':'')+v.toFixed(3)+'pp';},function(v){return (v>=0?'+':'')+v+'pp';});
}

