function renderGCCard(marca, btn) {
  _gcMarca = marca || _gcMarca || 'SCJ';

  /* Ativar botão correto */
  document.querySelectorAll('#ol-gc-brand-toggle .tgl').forEach(function(b){
    b.classList.remove('on','active');
    b.style.color = '#94A3B8';
    b.style.background = 'transparent';
    b.style.fontWeight = '700';
  });
  var activeBtn = btn || document.getElementById('ol-gc-btn-' + _gcMarca.toLowerCase());
  if(activeBtn){
    activeBtn.classList.add('active');
    activeBtn.style.color = '#F5E1A4';
    activeBtn.style.background = 'rgba(245,225,164,0.15)';
  }

  var kpisEl   = document.getElementById('ol-gc-kpis');
  var tbodyEl  = document.getElementById('ol-gc-tbody');
  var insightEl = document.getElementById('ol-gc-insights');
  if (!kpisEl || !tbodyEl || !insightEl) return;

  var data = GC_DATA[_gcMarca];
  if (!data || !data.grupos || data.grupos.length === 0) {
    kpisEl.innerHTML   = '<div style="color:#9CA3AF;font-size:12px;padding:10px;grid-column:1/-1;">Dados não disponíveis para ' + _gcMarca + '</div>';
    tbodyEl.innerHTML  = '<tr><td colspan="12" style="text-align:center;color:#6B7280;padding:20px;">Sem dados para ' + _gcMarca + '</td></tr>';
    insightEl.innerHTML = '';
    return;
  }

  /* Filtro de grupo */
  var grupos = data.grupos;
  var gcSel = document.getElementById('ol-sel-gc');
  var filtroGrupo = gcSel ? gcSel.value : '';
  if (filtroGrupo) {
    grupos = grupos.filter(function(g){ return g.nome === filtroGrupo || g.nome.toUpperCase() === filtroGrupo.toUpperCase(); });
  }

  /* Totais */
  var totPdvs25 = 0, totPdvs26 = 0, totVal25 = 0, totVal26 = 0, totCatVal25 = 0, totCatVal26 = 0;
  data.grupos.forEach(function(g){
    totPdvs25+=g.pdvs25; totPdvs26+=g.pdvs26; totVal25+=g.val25; totVal26+=g.val26;
    if(g.shr25>0) totCatVal25 += g.val25/g.shr25*100;
    if(g.shr26>0) totCatVal26 += g.val26/g.shr26*100;
  });

  /* Share médio ponderado por valor */
  var shrNumer25 = 0, shrNumer26 = 0;
  data.grupos.forEach(function(g){ shrNumer25 += g.shr25 * g.val25; shrNumer26 += g.shr26 * g.val26; });
  var shrMed25 = totVal25 > 0 ? shrNumer25 / totVal25 : 0;
  var shrMed26 = totVal26 > 0 ? shrNumer26 / totVal26 : 0;
  var shrVarMed = shrMed26 - shrMed25;

  var varPdvs = totPdvs26 - totPdvs25;
  var varPct  = totVal25 > 0 ? ((totVal26 - totVal25) / totVal25 * 100) : 0;
  var ac = '#F5E1A4';

  function fK(v){ return v >= 1000 ? 'R$' + (v/1000).toFixed(1) + 'M' : 'R$' + Math.round(v) + 'K'; }
  function fN(v){ return Math.round(v).toLocaleString('pt-BR'); }
  function fPP(v){ return (v >= 0 ? '+' : '') + v.toFixed(1) + 'pp'; }
  function fPct(v){ return (v >= 0 ? '+' : '') + v.toFixed(1) + '%'; }
  function col(v){ return v >= 0 ? '#34d399' : '#ef4444'; }

  /* KPIs */
  var kpiData = [
    { tag:'MARCA',           val:_gcMarca,                        sub:'Todos os grupos',       dlt:'',                             c:ac },
    { tag:'SHARE FY26 (MÉD)',val:shrMed26.toFixed(1)+'%',         sub:'FY25: '+shrMed25.toFixed(1)+'%', dlt:(shrVarMed>=0?'▲ +':'▼ ')+Math.abs(shrVarMed).toFixed(1)+'pp', c:col(shrVarMed) },
    { tag:'PDVs FY26',       val:fN(totPdvs26),                   sub:'FY25: '+fN(totPdvs25), dlt:(varPdvs>=0?'▲ +':'▼ ')+Math.abs(varPdvs).toLocaleString('pt-BR')+' PDVs', c:col(varPdvs) },
    { tag:'VALOR FY26',      val:fK(totVal26),                    sub:'FY25: '+fK(totVal25),  dlt:(varPct>=0?'▲ +':'▼ ')+Math.abs(varPct).toFixed(1)+'%', c:col(varPct) }
  ];
  kpisEl.innerHTML = kpiData.map(function(k){
    var topCol = k.c || ac;
    return '<div style="background:#E4EAF2;border-top:3px solid '+topCol+';border-left:1px solid rgba(94,153,208,0.35);border-right:1px solid rgba(94,153,208,0.35);border-bottom:1px solid rgba(94,153,208,0.35);border-radius:10px;padding:14px 16px;box-shadow:0 4px 12px rgba(10,40,80,0.10);position:relative;overflow:hidden;">'
      +'<div style="position:absolute;top:0;left:0;right:0;height:3px;background:linear-gradient(90deg,'+topCol+','+topCol+'88);"></div>'
      +'<div style="font-size:9px;font-weight:700;letter-spacing:0.1em;color:#475569;text-transform:uppercase;margin-bottom:6px;">'+k.tag+'</div>'
      +'<div style="font-size:22px;font-weight:700;color:'+topCol+';letter-spacing:-0.5px;">'+k.val+'</div>'
      +'<div style="font-size:10px;color:#64748B;margin-top:4px;">'+k.sub+'</div>'
      +(k.dlt?'<div style="font-size:10px;font-weight:600;color:'+k.c+';margin-top:3px;">'+k.dlt+'</div>':'')
      +'</div>';
  }).join('');

  /* Tabela */
  var rows = grupos.map(function(g){
    var varPdv = g.pdvs26 - g.pdvs25;
    var varVal = g.val25 > 0 ? ((g.val26 - g.val25) / g.val25 * 100) : 0;
    var catV25g = g.shr25 > 0 ? g.val25 / g.shr25 * 100 : 0;
    var catV26g = g.shr26 > 0 ? g.val26 / g.shr26 * 100 : 0;
    var varCat  = catV25g > 0 ? ((catV26g - catV25g) / catV25g * 100) : 0;
    var vs     = g.varShr;
    var cvs    = vs >= 0 ? '#34d399' : '#ef4444';
    var cvp    = varPdv >= 0 ? '#34d399' : '#ef4444';
    var cvv    = varVal >= 0 ? '#34d399' : '#ef4444';
    var cvc    = varCat >= 0 ? '#34d399' : '#ef4444';
    return '<tr style="border-bottom:1px solid rgba(94,153,208,0.18);">'
      +'<td style="padding:8px 10px;font-weight:600;color:#1E293B;">'+g.nome+'</td>'
      +'<td style="padding:8px 10px;text-align:right;color:#64748B;">'+fN(g.pdvs25)+'</td>'
      +'<td style="padding:8px 10px;text-align:right;color:#334155;font-weight:600;">'+fN(g.pdvs26)+'</td>'
      +'<td style="padding:8px 10px;text-align:right;color:'+cvp+';font-weight:700;">'+(varPdv>=0?'+':'')+varPdv+'</td>'
      +'<td style="padding:8px 10px;text-align:right;color:#64748B;">'+fN(g.val25)+'</td>'
      +'<td style="padding:8px 10px;text-align:right;color:#334155;font-weight:600;">'+fN(g.val26)+'</td>'
      +'<td style="padding:8px 10px;text-align:right;color:'+cvv+';font-weight:700;">'+fPct(varVal)+'</td>'
      +'<td style="padding:8px 8px;text-align:right;color:#64748B;border-left:2px solid rgba(94,153,208,0.25);">'+fN(g.shr25>0?g.val25/g.shr25*100:0)+'</td>'
      +'<td style="padding:8px 8px;text-align:right;color:#334155;">'+fN(g.shr26>0?g.val26/g.shr26*100:0)+'</td>'
      +'<td style="padding:8px 10px;text-align:right;color:'+cvc+';font-weight:700;">'+fPct(varCat)+'</td>'
      +'<td style="padding:8px 10px;text-align:right;color:#64748B;">'+g.shr25.toFixed(1)+'%</td>'
      +'<td style="padding:8px 10px;text-align:right;color:#334155;font-weight:600;">'+g.shr26.toFixed(1)+'%</td>'
      +'<td style="padding:8px 10px;text-align:right;color:'+cvs+';font-weight:700;">'+fPP(vs)+'</td>'
      +'</tr>';
  });
  /* Linha TOTAL */
  var totVarVal = totVal25 > 0 ? ((totVal26-totVal25)/totVal25*100) : 0;
  var totVarCat = totCatVal25 > 0 ? ((totCatVal26-totCatVal25)/totCatVal25*100) : 0;
  var totVarPdv = totPdvs26 - totPdvs25;
  rows.push('<tr style="border-top:2px solid rgba(94,153,208,0.45);background:rgba(94,153,208,0.08);">'
    +'<td style="padding:8px 10px;font-weight:800;color:#1D6FA8;">TOTAL</td>'
    +'<td style="padding:8px 10px;text-align:right;color:#475569;font-weight:700;">'+fN(totPdvs25)+'</td>'
    +'<td style="padding:8px 10px;text-align:right;color:#1E293B;font-weight:700;">'+fN(totPdvs26)+'</td>'
    +'<td style="padding:8px 10px;text-align:right;color:'+(totVarPdv>=0?'#34d399':'#ef4444')+';font-weight:700;">'+(totVarPdv>=0?'+':'')+totVarPdv+'</td>'
    +'<td style="padding:8px 10px;text-align:right;color:#475569;font-weight:700;">'+fN(totVal25)+'</td>'
    +'<td style="padding:8px 10px;text-align:right;color:#1E293B;font-weight:700;">'+fN(totVal26)+'</td>'
    +'<td style="padding:8px 10px;text-align:right;color:'+(totVarVal>=0?'#34d399':'#ef4444')+';font-weight:700;">'+fPct(totVarVal)+'</td>'
    +'<td style="padding:8px 8px;text-align:right;color:#475569;font-weight:700;border-left:2px solid rgba(94,153,208,0.25);">'+fN(totCatVal25)+'</td>'
    +'<td style="padding:8px 8px;text-align:right;color:#1E293B;font-weight:700;">'+fN(totCatVal26)+'</td>'
    +'<td style="padding:8px 10px;text-align:right;color:'+(totVarCat>=0?'#34d399':'#ef4444')+';font-weight:700;">'+fPct(totVarCat)+'</td>'
    +'<td style="padding:8px 10px;text-align:right;color:#475569;font-weight:700;">'+shrMed25.toFixed(1)+'%</td>'
    +'<td style="padding:8px 10px;text-align:right;color:#1E293B;font-weight:700;">'+shrMed26.toFixed(1)+'%</td>'
    +'<td style="padding:8px 10px;text-align:right;color:'+(shrVarMed>=0?'#34d399':'#ef4444')+';font-weight:700;">'+fPP(shrVarMed)+'</td>'
    +'</tr>');
  tbodyEl.innerHTML = rows.join('');

  /* Insights / Diagnóstico */
  var sorted = data.grupos.slice().sort(function(a,b){ return b.varShr - a.varShr; });
  var ganhos  = sorted.filter(function(g){ return g.varShr > 0; });
  var perdas  = sorted.filter(function(g){ return g.varShr < 0; }).reverse();
  var quedas  = data.grupos.filter(function(g){ return g.val26 < g.val25; })
                  .sort(function(a,b){ return ((a.val26-a.val25)/a.val25) - ((b.val26-b.val25)/b.val25); });

  function li(arr, col, fn){ return arr.slice(0,4).map(function(g){ return '<li style="margin-bottom:4px;"><span style="color:'+col+';font-weight:700;">'+fn(g)+'</span></li>'; }).join(''); }

  insightEl.innerHTML =
    '<div style="font-size:10px;font-weight:700;letter-spacing:0.1em;color:#F5E1A4;margin-bottom:12px;">DIAGNÓSTICO · ' + _gcMarca + '</div>'
    +'<div style="margin-bottom:12px;">'
    +'<div style="font-size:9px;font-weight:700;color:#34d399;margin-bottom:6px;">▲ GANHOS DE SHARE</div>'
    +'<ul style="margin:0;padding-left:12px;list-style:none;font-size:10px;color:#D1D5DB;">'+li(ganhos,'#34d399',function(g){ return g.nome+' '+fPP(g.varShr)+' → '+g.shr26.toFixed(1)+'%'; })+'</ul></div>'
    +'<div style="margin-bottom:12px;">'
    +'<div style="font-size:9px;font-weight:700;color:#ef4444;margin-bottom:6px;">▼ PERDAS DE SHARE</div>'
    +'<ul style="margin:0;padding-left:12px;list-style:none;font-size:10px;color:#D1D5DB;">'+li(perdas,'#ef4444',function(g){ return g.nome+' '+fPP(g.varShr)+' → '+g.shr26.toFixed(1)+'%'; })+'</ul></div>'
    +'<div>'
    +'<div style="font-size:9px;font-weight:700;color:#fbbf24;margin-bottom:6px;">→ OPORTUNIDADES</div>'
    +'<ul style="margin:0;padding-left:12px;list-style:none;font-size:10px;color:#D1D5DB;">'+li(quedas,'#fbbf24',function(g){
        var vv = g.val25 > 0 ? ((g.val26-g.val25)/g.val25*100) : 0;
        return g.nome+' queda '+fPct(vv);
      })+'</ul></div>';
}


function applyOLFilters(){
  renderOLTabs();
  /* Sync Grupo Cadeia select -> ESTUDO ED card */
  var gcSel = document.getElementById('ol-sel-gc');
  if(gcSel && typeof renderGCCard === 'function'){
    /* Valores do select agora são diretos — chaves de OL_GRUPO_DATA */
    _gcGrupo = gcSel.value ? gcSel.value : null;
    renderGCCard(_gcMarca, null);
  }
}
function clearOLFilters(){
  document.getElementById('ol-sel-ol').value='';
  var _bvReset=document.getElementById('ol-sel-bv'); if(_bvReset) _bvReset.value='';
  renderOLTabs();
}

// ── SHARE helpers ─────────────────────────────────────
function getShareTotals(){
  var keys=getOLKeys(), bv=getBV(), t={pdvs:0,pos25:0,pos26:0,catAnt:0,catAt:0,propAnt:0,propAt:0};
  keys.forEach(function(k){
    var d=OL_SHARE_DATA[k];
    if(!bv){t.pdvs+=d.pdvsTotal;t.pos25+=d.posit25;t.pos26+=d.posit26;t.catAnt+=d.catAnt;t.catAt+=d.catAtual;t.propAnt+=d.propAnt;t.propAt+=d.propAtual;}
    else{
      var c=d.clients.find(function(x){return x.name===bv;});
      if(c){t.pdvs+=c.pdvs;t.catAnt+=c.catAnt;t.catAt+=c.catAt;t.propAnt+=c.propAnt;t.propAt+=c.propAt;}
    }
  });
  t.shareAnt=t.catAnt>0?t.propAnt/t.catAnt*100:0;
  t.shareAt=t.catAt>0?t.propAt/t.catAt*100:0;
  t.shareVar=t.shareAt-t.shareAnt;
  return t;
}
function getShareClients(){
  var keys=getOLKeys(), bv=getBV(), seen={};
  keys.forEach(function(k){
    OL_SHARE_DATA[k].clients.forEach(function(c){
      if(bv && c.name!==bv) return;
      if(!seen[c.name]||c.catAt>seen[c.name].catAt){var cc=JSON.parse(JSON.stringify(c));cc._ol=k;seen[c.name]=cc;}
    });
  });
  return Object.values(seen).sort(function(a,b){return b.catAt-a.catAt;}).slice(0,20);
}

// ── SO helpers ────────────────────────────────────────
function getSOTotals(){
  var keys=getOLKeys(), bv=getBV(), t={pdvs:0,so25:0,so26:0,p25:0,p26:0};
  keys.forEach(function(k){
    var d=SO_DATA[k];
    if(!bv){t.pdvs+=d.pdvs;t.so25+=d.so25;t.so26+=d.so26;t.p25+=d.p25;t.p26+=d.p26;}
    else{
      var c=d.clients.find(function(x){return x.n===bv;});
      if(c){t.pdvs+=c.pdvs;t.so25+=c.so25;t.so26+=c.so26;t.p25+=c.p25;t.p26+=c.p26;}
    }
  });
  t.var=t.so25>0?((t.so26-t.so25)/t.so25*100):null;
  return t;
}
function getSOClients(){
  var keys=getOLKeys(), bv=getBV(), seen={};
  keys.forEach(function(k){
    SO_DATA[k].clients.forEach(function(c){
      if(bv && c.n!==bv) return;
      if(!seen[c.n]||c.so26>seen[c.n].so26){var cc=JSON.parse(JSON.stringify(c));cc._ol=k;seen[c.n]=cc;}
    });
  });
  return Object.values(seen).sort(function(a,b){return b.so26-a.so26;}).slice(0,20);
}

// ── RENDER ────────────────────────────────────────────
function renderOLTabs(){
  if(!document.getElementById('ol-sel-ol')) return; // aba OLs removida em 04/08 — evita TypeError no init
  var ac=getAC(), lbl=getLabel();
  var olKey=document.getElementById('ol-sel-ol').value;

  // Share pill (sempre visível)
  var t=getShareTotals();
  var sc=t.shareVar>=0?'#34d399':'#ef4444';
  var pill=document.getElementById('ol-share-pill');
  pill.textContent='Share '+t.shareAt.toFixed(1)+'% '+(t.shareVar>=0?'▲ +':'▼ ')+Math.abs(t.shareVar).toFixed(1)+'pp';
  pill.style.color=sc; pill.style.borderColor=sc+'44'; pill.style.background=sc+'11';

  if(curSection==='share') renderShare(ac,lbl,olKey,t);
  else if(curSection==='so') renderSO(ac,lbl,olKey);
  else if(curSection==='perf') renderPerf(olKey);
    else if(curSection==='track') renderTrack(olKey);
}

function renderShare(ac,lbl,olKey,t){
  // KPIs
  var positD=t.pos26-t.pos25;
  var catV=t.catAnt>0?((t.catAt-t.catAnt)/t.catAnt*100).toFixed(1):'—';
  var propV=t.propAnt>0?((t.propAt-t.propAnt)/t.propAnt*100).toFixed(1):'—';
  var kdata=[
    {tag:'PDVs TOTAL',val:fN(t.pdvs),sub:'Carteira ativa',dlt:(positD>=0?'▲':'▼')+Math.abs(positD)+' posit vs FY25',c:ac},
    {tag:'POSITIVAÇÃO FY26',val:fN(t.pos26),sub:'FY25: '+fN(t.pos25),dlt:(positD>=0?'▲':'▼')+Math.abs(positD)+' vs FY25',c:positD>=0?'#34d399':'#ef4444'},
    {tag:'CATEGORIA FY26',val:'R$'+fN(t.catAt)+'K',sub:'FY25: R$'+fN(t.catAnt)+'K',dlt:(t.catAt>=t.catAnt?'▲':'▼')+catV+'%',c:t.catAt>=t.catAnt?'#34d399':'#ef4444'},
    {tag:'PRÓPRIO FY26',val:'R$'+fN(t.propAt)+'K',sub:'FY25: R$'+fN(t.propAnt)+'K',dlt:(t.propAt>=t.propAnt?'▲':'▼')+propV+'%',c:t.propAt>=t.propAnt?'#34d399':'#ef4444'},
    {tag:'SHARE FY26',val:t.shareAt.toFixed(1)+'%',sub:'FY25: '+t.shareAnt.toFixed(1)+'%',dlt:(t.shareVar>=0?'▲ +':'▼ ')+Math.abs(t.shareVar).toFixed(1)+'pp',c:t.shareVar>=0?'#34d399':'#ef4444'}
  ];
  document.getElementById('ol-kpis-share').innerHTML=kdata.map(function(k){
    return '<div class="ol-kpi" style="--c:'+k.c+'"><div class="tag">'+k.tag+'</div><div class="val">'+k.val+'</div><div class="sub">'+k.sub+'</div>'+(k.dlt?'<div class="dlt'+dCls(parseFloat(k.dlt))+'">'+k.dlt+'</div>':'')+'</div>';
  }).join('');
  document.getElementById('ol-tbl-h-share').textContent='Clientes · '+lbl+' · Share ED';

  // Table
  var clients=getShareClients();
  var rows=clients.map(function(c){
    var cv=c.catAnt>0?((c.catAt-c.catAnt)/c.catAnt*100).toFixed(1):'—';
    var pv=c.propAnt>0?((c.propAt-c.propAnt)/c.propAnt*100).toFixed(1):'—';
    var cc=c.catAt>=c.catAnt?'#34d399':'#ef4444';
    var pc=c.propAt>=c.propAnt?'#34d399':'#ef4444';
    var sc=c.shareVar>=0?'#34d399':'#ef4444';
    var olBadge=!olKey?'<span style="font-size:8px;font-weight:800;padding:1px 5px;border-radius:3px;background:'+OL_COLORS[c._ol]+'18;border:.5px solid '+OL_COLORS[c._ol]+'44;color:'+OL_COLORS[c._ol]+';margin-right:4px">'+OL_SHARE_DATA[c._ol].label+'</span>':'';
    var uhtml='<div class="ol-ufs">'+olBadge+(c.ufs||[]).map(function(u){
      var uc=UF_C[u.uf]||'#64748b';
      return '<span class="ol-ufb" style="background:'+uc+'18;border:.5px solid '+uc+'44;color:'+uc+'">'+u.uf+'</span><span style="font-size:9px;color:#4a5568;margin-right:4px">'+u.sb.toFixed(1)+'%</span>';
    }).join('')+'</div>';
    return '<tr><td><span class="ol-cn">'+c.name+'</span>'+uhtml+'</td>'
      +'<td style="color:#D1D5DB">'+fN(c.pdvs)+'</td>'
      +'<td style="color:#4a5568">'+fN(c.catAnt)+'</td><td style="color:#D1D5DB">'+fN(c.catAt)+'</td><td style="color:'+cc+';font-weight:700">'+cv+'%</td>'
      +'<td style="color:#4a5568">'+fN(c.propAnt)+'</td><td style="color:#D1D5DB">'+fN(c.propAt)+'</td><td style="color:'+pc+';font-weight:700">'+pv+'%</td>'
      +'<td style="color:#4a5568">'+c.shareAnt.toFixed(1)+'%</td><td style="color:#fbbf24;font-weight:700">'+c.shareAt.toFixed(1)+'%</td>'
      +'<td style="color:'+sc+';font-weight:700">'+sgn(c.shareVar)+'</td></tr>';
  }).join('');
  document.getElementById('ol-tbody-share').innerHTML=rows||'<tr><td colspan="11" style="text-align:center;color:#4a5568;padding:20px">Sem resultados</td></tr>';

  // Diag
  renderDiagShare(ac,lbl,t,clients);
}

function renderSO(ac,lbl,olKey){
  var t=getSOTotals();
  var varT=t.var, ac2=t.so26>=t.so25?'#34d399':'#ef4444';
  var positD=t.p26-t.p25;
  var kdata=[
    {tag:'PDVs COM SO FY26',val:fN(t.p26),sub:'FY25: '+fN(t.p25),dlt:(positD>=0?'▲':'▼')+Math.abs(positD)+' PDVs vs FY25',c:positD>=0?'#34d399':'#ef4444'},
    {tag:'COBERTURA FY26',val:t.pdvs>0?(t.p26/t.pdvs*100).toFixed(1)+'%':'—',sub:fN(t.pdvs)+' PDVs total',dlt:'',c:ac},
    {tag:'SELL OUT FY25',val:fN(t.so25)+' un',sub:'Jul–Dez 2024',dlt:'',c:'#60a5fa'},
    {tag:'SELL OUT FY26',val:fN(t.so26)+' un',sub:'Jul–Dez 2025',dlt:varT!==null?(t.so26>=t.so25?'▲ +':'▼ ')+Math.abs(varT)+'%':'—',c:ac2},
    {tag:'VARIAÇÃO SO',val:varT!==null?(varT>=0?'+':'')+varT+'%':'—',sub:'FY26 vs FY25',dlt:'',c:ac2}
  ];
  document.getElementById('ol-kpis-so').innerHTML=kdata.map(function(k){
    return '<div class="ol-kpi" style="--c:'+k.c+'"><div class="tag">'+k.tag+'</div><div class="val">'+k.val+'</div><div class="sub">'+k.sub+'</div>'+(k.dlt?'<div class="dlt'+dCls(parseFloat(k.dlt))+'">'+k.dlt+'</div>':'')+'</div>';
  }).join('');
  document.getElementById('ol-tbl-h-so').textContent='Bandeiras · '+lbl+' · Sell Out';

  var clients=getSOClients();
  var rows=clients.map(function(c){
    var vc=c.so26>=c.so25?'#34d399':'#ef4444';
    var pDelta=c.p26-c.p25;
    var pDeltaC=pDelta>=0?'#34d399':'#ef4444';
    var avgFy25=c.p25>0?(c.so25/c.p25).toFixed(1):'—';
    var avgFy26=c.p26>0?(c.so26/c.p26).toFixed(1):'—';
    var varStr=c.var!==null?(c.var>=0?'▲ +':'▼ ')+Math.abs(c.var)+'%':'—';
    var pct25=c.pdvs>0?Math.round(c.p25/c.pdvs*100):0;
    var pct26=c.pdvs>0?Math.round(c.p26/c.pdvs*100):0;
    var olBadge=!olKey?'<span style="font-size:8px;font-weight:800;padding:1px 5px;border-radius:3px;background:'+OL_COLORS[c._ol]+'18;border:.5px solid '+OL_COLORS[c._ol]+'44;color:'+OL_COLORS[c._ol]+';margin-right:4px">'+SO_DATA[c._ol].label+'</span>':'';
    var positBar='<div class="ol-pbar-wrap"><div class="ol-pbar-track"><div class="ol-pbar-fill" style="width:'+pct26+'%;background:'+(pct26>=pct25?'#34d399':'#ef4444')+'"></div></div><span class="ol-pbar-pct" style="color:'+(pct26>=pct25?'#34d399':'#ef4444')+'">'+pct26+'%</span></div>';
    return '<tr>'
      +'<td><span class="ol-cn">'+olBadge+c.n+'</span>'+positBar+'</td>'
      +'<td style="color:#D1D5DB">'+fN(c.pdvs)+'</td>'
      +'<td style="color:#4a5568">'+fN(c.p25)+'</td>'
      +'<td style="color:#D1D5DB">'+fN(c.p26)+'</td>'
      +'<td style="color:'+pDeltaC+';font-weight:700">'+(pDelta>=0?'+':'')+pDelta+'</td>'
      +'<td style="color:#4a5568">'+fN(c.so25)+'</td>'
      +'<td style="color:#D1D5DB">'+fN(c.so26)+'</td>'
      +'<td style="color:'+vc+';font-weight:700">'+varStr+'</td>'
      +'<td style="color:#4a5568">'+avgFy25+'</td>'
      +'<td style="color:#fbbf24;font-weight:700">'+avgFy26+'</td>'
      +'</tr>';
  }).join('');
  document.getElementById('ol-tbody-so').innerHTML=rows||'<tr><td colspan="10" style="text-align:center;color:#4a5568;padding:20px">Sem resultados</td></tr>';

  renderDiagSO(ac,lbl,t,clients);
}

function renderDiagShare(ac,lbl,t,clients){
  var sorted=clients.slice().sort(function(a,b){return b.shareVar-a.shareVar;});
  var gainers=sorted.filter(function(c){return c.shareVar>0;}).slice(0,3);
  var losers=sorted.filter(function(c){return c.shareVar<0;}).slice(-3).reverse();
  var fortes=[],atencao=[],oport=[];
  if(t.shareVar>=0) fortes.push('Share subindo '+sgn(t.shareVar)+'pp — de '+t.shareAnt.toFixed(1)+'% para '+t.shareAt.toFixed(1)+'%');
  else atencao.push('Share recuando '+sgn(t.shareVar)+'pp — de '+t.shareAnt.toFixed(1)+'% para '+t.shareAt.toFixed(1)+'%');
  var pd=t.pos26-t.pos25;
  if(pd>=0) fortes.push('Positivação estável/crescendo · '+fN(t.pos26)+' PDVs ativos FY26');
  else atencao.push('Positivação caiu '+pd+' PDVs · '+fN(t.pos26)+' ativos');
  if(gainers.length) fortes.push('Ganho de share: '+gainers.map(function(c){return c.name+' ('+sgn(c.shareVar)+'pp)';}).join(', '));
  if(losers.length) atencao.push('Queda de share: '+losers.map(function(c){return c.name+' ('+sgn(c.shareVar)+'pp)';}).join(', '));
  oport.push(fN(t.pdvs-t.pos26)+' PDVs sem positivação FY26');
  if(t.propAt<t.propAnt) oport.push('Gap Próprio: R$'+fN(t.propAnt-t.propAt)+'K vs FY25');
  function lis(arr,col,mk){return arr.map(function(s){return '<li><span class="ol-mk" style="color:'+col+'">'+mk+'</span>'+s+'</li>';}).join('');}
  var sc=t.shareVar>=0?'#34d399':'#ef4444';
  document.getElementById('ol-diag-share').innerHTML=
    '<div class="ol-card-hd"><div><h2 style="color:'+ac+'">🔍 DIAGNÓSTICO SHARE · '+lbl+'</h2><p>FY25→FY26</p></div>'
    +'<span class="pill" style="color:'+sc+';border-color:'+sc+'44;background:'+sc+'11">Share '+t.shareAt.toFixed(1)+'% '+(t.shareVar>=0?'▲ +':'▼ ')+Math.abs(t.shareVar).toFixed(1)+'pp</span></div>'
    +'<div class="ol-dg">'
    +'<div><div class="ol-dg-h" style="color:#34d399"><span class="ol-dg-dot" style="background:#34d399"></span>PONTOS FORTES</div><ul>'+lis(fortes,'#34d399','✓ ')+'</ul></div>'
    +'<div><div class="ol-dg-h" style="color:#06b6d4"><span class="ol-dg-dot" style="background:#06b6d4"></span>PONTOS DE ATENÇÃO</div><ul>'+lis(atencao,'#06b6d4','⚠ ')+'</ul></div>'
    +'<div><div class="ol-dg-h" style="color:#fbbf24"><span class="ol-dg-dot" style="background:#fbbf24"></span>OPORTUNIDADES</div><ul>'+lis(oport,'#fbbf24','→ ')+'</ul></div>'
    +'</div>';
}

function renderDiagSO(ac,lbl,t,clients){
  var sorted=clients.slice().sort(function(a,b){return (b.var||0)-(a.var||0);});
  var gainers=sorted.filter(function(c){return c.var>0;}).slice(0,3);
  var losers=sorted.filter(function(c){return c.var<0;}).slice(-3).reverse();
  var fortes=[],atencao=[],oport=[];
  if(t.var!==null&&t.var>=0) fortes.push('Sell Out crescendo '+(t.var>=0?'+':'')+t.var.toFixed(1)+'% vs FY25');
  else if(t.var!==null) atencao.push('Sell Out recuando '+t.var.toFixed(1)+'% — '+fN(t.so25)+' → '+fN(t.so26)+' un');
  var pd=t.p26-t.p25;
  if(pd>=0) fortes.push('Cobertura estável · '+fN(t.p26)+' PDVs vendendo FY26 ('+(t.pdvs>0?(t.p26/t.pdvs*100).toFixed(0)+'%':'')+')');
  else atencao.push('Cobertura caiu '+Math.abs(pd)+' PDVs · '+fN(t.p26)+' ativos vs '+fN(t.p25)+' FY25');
  if(gainers.length) fortes.push('Crescimento SO: '+gainers.map(function(c){return c.n+' ('+(c.var>=0?'+':'')+c.var.toFixed(1)+'%)';}).join(', '));
  if(losers.length) atencao.push('Queda SO: '+losers.map(function(c){return c.n+' ('+c.var.toFixed(1)+'%)';}).join(', '));
  oport.push(fN(t.pdvs-t.p26)+' PDVs sem venda FY26 de '+fN(t.pdvs)+' totais');
  function lis(arr,col,mk){return arr.map(function(s){return '<li><span class="ol-mk" style="color:'+col+'">'+mk+'</span>'+s+'</li>';}).join('');}
  var vc=t.so26>=t.so25?'#34d399':'#ef4444';
  document.getElementById('ol-diag-so').innerHTML=
    '<div class="ol-card-hd"><div><h2 style="color:'+ac+'">🛒 DIAGNÓSTICO SELL OUT · '+lbl+'</h2><p>Acumulado Jul–Dez · FY25 vs FY26</p></div>'
    +'<span class="pill" style="color:'+vc+';border-color:'+vc+'44;background:'+vc+'11">SO FY26: '+fN(t.so26)+' un '+(t.var!==null?(t.so26>=t.so25?'▲ +':'▼ ')+Math.abs(t.var).toFixed(1)+'%':'')+'</span></div>'
    +'<div class="ol-dg">'
    +'<div><div class="ol-dg-h" style="color:#34d399"><span class="ol-dg-dot" style="background:#34d399"></span>PONTOS FORTES</div><ul>'+lis(fortes,'#34d399','✓ ')+'</ul></div>'
    +'<div><div class="ol-dg-h" style="color:#06b6d4"><span class="ol-dg-dot" style="background:#06b6d4"></span>PONTOS DE ATENÇÃO</div><ul>'+lis(atencao,'#06b6d4','⚠ ')+'</ul></div>'
    +'<div><div class="ol-dg-h" style="color:#fbbf24"><span class="ol-dg-dot" style="background:#fbbf24"></span>OPORTUNIDADES</div><ul>'+lis(oport,'#fbbf24','→ ')+'</ul></div>'
    +'</div>';
}

// INIT
renderOLTabs();

  /* ========== PERFORMANCE ========== */
  function fmtN(v){return Math.round(v).toLocaleString('pt-BR');}
  function pctColor(p){
    if(p>=100) return '#22c55e';
    if(p>=80)  return '#f59e0b';
    return '#ef4444';
  }
  function pctBg(p){
    if(p>=100) return 'rgba(34,197,94,0.1)';
    if(p>=80)  return 'rgba(245,158,11,0.1)';
    return 'rgba(239,68,68,0.1)';
  }

  function renderPerf(olFilter){
    const OLS=['mg','ne','prsc','rj','rs','spc','spi'];
    const activeOLs = olFilter ? [olFilter] : OLS;

    // FYTD Summary table
    let fytdHtml = `
      <h4 style="margin:0 0 12px;color:#4a5568;font-size:.85rem;text-transform:uppercase;letter-spacing:.06em">Resumo FYTD por OL</h4>
      <div style="overflow-x:auto">
      <table style="width:100%;border-collapse:collapse;font-size:.875rem">
        <thead><tr style="border-bottom:2px solid rgba(255,255,255,.07)">
          <th style="text-align:left;padding:8px 10px;color:#4a5568;font-weight:600">OL</th>
          <th style="text-align:right;padding:8px 10px;color:#4a5568;font-weight:600">Target FYTD</th>
          <th style="text-align:right;padding:8px 10px;color:#4a5568;font-weight:600">Realizado FYTD</th>
          <th style="text-align:right;padding:8px 10px;color:#4a5568;font-weight:600">% Atingimento</th>
          <th style="padding:8px 10px;min-width:140px;color:#4a5568;font-weight:600">Progresso</th>
        </tr></thead><tbody>`;

    OLS.forEach(k=>{
      const d=PERF_DATA[k]; if(!d) return;
      const show = !olFilter || k===olFilter;
      if(!show) return;
      const p=d.fytdPct;
      const bar=Math.min(p,100);
      fytdHtml+=`<tr style="border-bottom:1px solid rgba(255,255,255,.07);background:${pctBg(p)}">
        <td style="padding:10px;font-weight:600;color:#D1D5DB">${d.label}</td>
        <td style="text-align:right;padding:10px;color:#4a5568">${fmtN(d.fytdTarget)}</td>
        <td style="text-align:right;padding:10px;font-weight:600;color:#D1D5DB">${fmtN(d.fytdReal)}</td>
        <td style="text-align:right;padding:10px;font-weight:700;color:${pctColor(p)}">${p.toFixed(1)}%</td>
        <td style="padding:10px">
          <div style="background:rgba(255,255,255,.07);border-radius:99px;height:8px;position:relative">
            <div style="background:${pctColor(p)};width:${bar}%;height:100%;border-radius:99px;transition:width .4s"></div>
          </div>
        </td>
      </tr>`;
    });
    fytdHtml+='</tbody></table></div>';
    document.getElementById('ol-perf-fytd').innerHTML=fytdHtml;

    // Monthly performance for each active OL
    const MES_LABELS=['Jul/25','Ago/25','Set/25','Out/25','Nov/25','Dez/25','Jan/26','Fev/26','Mar/26','Abr/26','Mai/26','Jun/26'];
    let monthHtml='';

    activeOLs.forEach(k=>{
      const d=PERF_DATA[k]; if(!d) return;
      monthHtml+=`
        <h4 style="margin:24px 0 12px;color:#4a5568;font-size:.85rem;text-transform:uppercase;letter-spacing:.06em">${d.label} – Mensal</h4>
        <div style="overflow-x:auto">
        <table style="width:100%;border-collapse:collapse;font-size:.85rem">
          <thead><tr style="border-bottom:2px solid rgba(255,255,255,.07)">
            <th style="text-align:left;padding:8px;color:#4a5568;font-weight:600">Mês</th>
            <th style="text-align:right;padding:8px;color:#4a5568;font-weight:600">Target</th>
            <th style="text-align:right;padding:8px;color:#4a5568;font-weight:600">Realizado</th>
            <th style="text-align:right;padding:8px;color:#4a5568;font-weight:600">vs Target</th>
            <th style="padding:8px;min-width:120px;color:#4a5568;font-weight:600">Progresso</th>
          </tr></thead><tbody>`;
      d.months.forEach((_,i)=>{
        const t=d.target[i], r=d.realizado[i], p=d.pct[i];
        const bar=Math.min(p,100);
        const isLast=(i===d.months.length-1);
        monthHtml+=`<tr style="border-bottom:1px solid rgba(255,255,255,.07);${isLast?'font-weight:600;':''}background:${pctBg(p)}">
          <td style="padding:8px;color:#D1D5DB">${MES_LABELS[i]}</td>
          <td style="text-align:right;padding:8px;color:#4a5568">${fmtN(t)}</td>
          <td style="text-align:right;padding:8px;color:#D1D5DB">${fmtN(r)}</td>
          <td style="text-align:right;padding:8px;font-weight:700;color:${pctColor(p)}">${p.toFixed(1)}%</td>
          <td style="padding:8px">
            <div style="background:rgba(255,255,255,.07);border-radius:99px;height:7px">
              <div style="background:${pctColor(p)};width:${bar}%;height:100%;border-radius:99px"></div>
            </div>
          </td>
        </tr>`;
      });
      monthHtml+='</tbody></table></div>';
    });

    document.getElementById('ol-perf-monthly').innerHTML=monthHtml;
  }

      var curTrackOL = null;
      function setTrackOL(ol, btn){
        curTrackOL = ol;
        document.querySelectorAll('.tfl').forEach(function(b){b.classList.remove('on');});
        btn.classList.add('on');
        renderTrack(ol);
      }

function renderTrack(olFilter){
  var d=TRACK_DATA;
  var k=olFilter||curTrackOL||null;
  var ols=k?[k]:Object.keys(d.ating);
  var labels={'mg':'OL MG','ne':'OL NE','prsc':'OL PR/SC','rj':'OL RJ','rs':'OL RS','spc':'OL SPC','spi':'OL SPI'};
  var prods=d.prods||[];
  var mixes=['D','C','B','A'];
  var mixW=0.05, solW=0.70, lncW=0.02;

  // helper
  function pBar(pct,color){
    var w=Math.min(pct,100);
    return '<div style="background:rgba(255,255,255,.07);border-radius:3px;height:6px;min-width:60px;flex:1">'
      +'<div style="background:'+color+';width:'+w+'%;height:6px;border-radius:3px"></div></div>';
  }
  function pColor(p){return p>=100?'#34d399':p>=80?'#fbbf24':'#ef4444';}
  function pFmt(v){return (v*100).toFixed(1)+'%';}

  var cards=ols.map(function(o){
    var so=d.so[o]||{}; var dist=d.dist[o]||{}; var lanc=d.lanc[o]||{}; var mes=d.mes[o]||{};
    var prem=d.ating[o]||0;
    var premColor=pColor(prem);

    // SO FYTD atingimento
    var soReal=so.real||0; var soTgt=so.tgt||1;
    var soPct=Math.min(soReal/soTgt*100,100);
    var soFinal=soPct/100*solW;

    // Mar/26 mensal
    var mesReal=mes.real||0; var mesTgt=mes.tgt||1; var mesPct=mes.pct||0;
    var mesColor=pColor(mesPct);

    // Dist per mix
    var distRows=mixes.map(function(mx){
      var t=(dist.tgt||{})[mx]||0; var r=(dist.fytd||{})[mx]||0;
      var p=t>0?Math.min(r/t*100,100):0;
      var c=pColor(p);
      return '<tr>'
        +'<td style="padding:4px 8px;color:#D1D5DB;font-size:11px">vs target Mix '+mx+'</td>'
        +'<td style="padding:4px 8px;color:#4a5568;font-size:11px;text-align:center">5%</td>'
        +'<td style="padding:4px 8px"><div style="display:flex;align-items:center;gap:8px">'+pBar(p,c)
        +'<span style="font-size:11px;color:'+c+';min-width:36px;text-align:right">'+p.toFixed(0)+'%</span></div></td>'
        +'<td style="padding:4px 8px;color:'+c+';font-size:11px;text-align:right;font-weight:700">'+pFmt(p/100*mixW)+'</td>'
        +'</tr>';
    }).join('');
    var distTotal=mixes.reduce(function(s,mx){
      var t=(dist.tgt||{})[mx]||0;var r=(dist.fytd||{})[mx]||0;
      return s+(t>0?Math.min(r/t,1)*mixW:0);
    },0);

    // Lanc per product
    var lncRows=(lanc.prods||prods).map(function(p,i){
      var pr=lanc.pct?lanc.pct[i]:0;
      var c=pColor(pr);
      return '<tr>'
        +'<td style="padding:4px 8px;color:#D1D5DB;font-size:11px">'+p+'</td>'
        +'<td style="padding:4px 8px;color:#4a5568;font-size:11px;text-align:center">2%</td>'
        +'<td style="padding:4px 8px"><div style="display:flex;align-items:center;gap:8px">'+pBar(pr,c)
        +'<span style="font-size:11px;color:'+c+';min-width:36px;text-align:right">'+pr.toFixed(0)+'%</span></div></td>'
        +'<td style="padding:4px 8px;color:'+c+';font-size:11px;text-align:right;font-weight:700">'+pFmt(Math.min(pr/100,1)*lncW)+'</td>'
        +'</tr>';
    }).join('');
    var lncTotal=(lanc.pct||[]).reduce(function(s,p){return s+Math.min(p/100,1)*lncW;},0);

    var tblStyle='border-collapse:collapse;width:100%';
    var thStyle='padding:6px 8px;color:#4a5568;font-size:10px;text-align:left;border-bottom:1px solid rgba(255,255,255,.07);font-weight:600;letter-spacing:.3px';
    var grpStyle='padding:8px 8px 4px;font-size:12px;font-weight:800;color:#D1D5DB;background:rgba(255,255,255,.03)';

    return '<div style="background:rgba(255,255,255,.03);border:1px solid rgba(234,179,8,0.12);border-radius:10px;overflow:hidden;margin-bottom:16px">'
      // Header
      +'<div style="display:flex;align-items:center;justify-content:space-between;padding:12px 16px;background:rgba(255,255,255,.05);border-bottom:1px solid rgba(255,255,255,.08)">'
      +'<span style="font-size:14px;font-weight:800;color:#e2e8f0">'+(labels[o]||o)+'</span>'
      +'<div style="display:flex;align-items:center;gap:10px">'
      +'<span style="font-size:11px;color:#4a5568">Premiação Final</span>'
      +'<span style="font-size:20px;font-weight:900;color:'+premColor+'">'+prem.toFixed(1)+'%</span>'
      +'</div></div>'
      // Table
      +'<table style="'+tblStyle+'">'
      +'<thead><tr>'
      +'<th style="'+thStyle+'">KPI</th><th style="'+thStyle+';text-align:center">Pontuação</th>'
      +'<th style="'+thStyle+'">Realizado</th><th style="'+thStyle+';text-align:right">% Final</th>'
      +'</tr></thead><tbody>'
      // Distribuição group header
      +'<tr><td colspan="4" style="'+grpStyle+'">📦 Expandindo Distribuição</td></tr>'
      +distRows
      +'<tr style="background:rgba(255,255,255,.02)">'
      +'<td style="padding:4px 8px 8px;color:#64748b;font-size:10px;font-style:italic">Subtotal Distribuição</td>'
      +'<td style="padding:4px 8px 8px;color:#4a5568;font-size:11px;text-align:center">20%</td>'
      +'<td></td>'
      +'<td style="padding:4px 8px 8px;color:#D1D5DB;font-size:11px;text-align:right;font-weight:700">'+pFmt(distTotal)+'</td>'
      +'</tr>'
      // Sell Out group
      +'<tr><td colspan="4" style="'+grpStyle+'">💰 Sell Out FYTD</td></tr>'
      +'<tr>'
      +'<td style="padding:4px 8px;color:#D1D5DB;font-size:11px">vs target por OL</td>'
      +'<td style="padding:4px 8px;color:#4a5568;font-size:11px;text-align:center">70%</td>'
      +'<td style="padding:4px 8px"><div style="display:flex;align-items:center;gap:8px">'
      +pBar(soPct,pColor(soPct))
      +'<span style="font-size:11px;color:'+pColor(soPct)+';min-width:36px;text-align:right">'+soPct.toFixed(0)+'%</span>'
      +'<span style="font-size:10px;color:#4a5568">('+fN(Math.round(soReal))+'/'+fN(Math.round(soTgt))+')</span>'
      +'</div></td>'
      +'<td style="padding:4px 8px;color:'+pColor(soPct)+';font-size:11px;text-align:right;font-weight:700">'+pFmt(soFinal)+'</td>'
      +'</tr>'
      // SO Mensal Mar/26 (informativo)
      +'<tr style="background:rgba(255,255,255,.01)">'
      +'<td style="padding:4px 8px;color:#64748b;font-size:10px;font-style:italic">↳ Mar/26 mensal</td>'
      +'<td style="padding:4px 8px;color:#3d4451;font-size:10px;text-align:center">—</td>'
      +'<td style="padding:4px 8px"><div style="display:flex;align-items:center;gap:8px">'
      +pBar(mesPct,mesColor)
      +'<span style="font-size:10px;color:'+mesColor+';min-width:36px;text-align:right">'+mesPct.toFixed(0)+'%</span>'
      +'<span style="font-size:9px;color:#3d4451">('+fN(mesReal)+'/'+fN(mesTgt)+')</span>'
      +'</div></td>'
      +'<td style="padding:4px 8px;color:'+mesColor+';font-size:10px;text-align:right;font-style:italic">'+mesPct.toFixed(1)+'%</td>'
      +'</tr>'
      // Lançamento group
      +'<tr><td colspan="4" style="'+grpStyle+'">🚀 Sell Out Lançamento</td></tr>'
      +lncRows
      +'<tr style="background:rgba(255,255,255,.02)">'
      +'<td style="padding:4px 8px 8px;color:#64748b;font-size:10px;font-style:italic">Subtotal Lançamento</td>'
      +'<td style="padding:4px 8px 8px;color:#4a5568;font-size:11px;text-align:center">10%</td>'
      +'<td></td>'
      +'<td style="padding:4px 8px 8px;color:#D1D5DB;font-size:11px;text-align:right;font-weight:700">'+pFmt(lncTotal)+'</td>'
      +'</tr>'
      // Total
      +'<tr style="border-top:2px solid rgba(255,255,255,.12);background:rgba(255,255,255,.04)">'
      +'<td style="padding:10px 8px;font-size:13px;font-weight:800;color:#e2e8f0" colspan="3">🏆 Premiação Final</td>'
      +'<td style="padding:10px 8px;font-size:16px;font-weight:900;color:'+premColor+';text-align:right">'+prem.toFixed(1)+'%</td>'
      +'</tr>'
      +'</tbody></table></div>';
  }).join('');

  document.getElementById('ol-track-body').innerHTML = cards || '<p style="color:#94A3B8;padding:20px">Sem dados</p>';
}

var _olTabsInited=false;
function initOLTabs(){if(!_olTabsInited){_olTabsInited=true;renderOLTabs();}}
(function(){
  var _orig=window.showPanel;
  window.showPanel=function(id){
    if(typeof _orig==='function')_orig.apply(this,arguments);
    if(id==='panel-ol')setTimeout(initOLTabs,50);
  };
  window.addEventListener('load',function(){
    var p=document.getElementById('panel-ol');
    if(p&&p.offsetParent!==null)initOLTabs();
  });
})();

